553	// 查询返回的登记结束时间与实际结束时间可被调用方随意修改，但账本不变。
554	func TestQueryMutationDoesNotChangeLedger(t *testing.T) {
555		now, setNow := fixedClock(at(0))
556		b := NewBook(WithClock(now))
557		must := func(r RegisterRequest) {
558			t.Helper()
559			if err := b.RegisterVersion(r); err != nil {
560				t.Fatalf("register: %v", err)
561			}
562		}
563		must(RegisterRequest{ItemID: "seat", VersionID: "old", UnitPrice: 100, Start: at(0), End: atPtr(100)})
564		must(RegisterRequest{ItemID: "seat", VersionID: "new", UnitPrice: 200, Start: at(40), Replaces: "old"})
565	
566		first, err := b.ItemVersions("seat")
567		if err != nil {
568			t.Fatal(err)
569		}
570		// old 的登记结束为 100，实际结束被截断到 40
571		var old, nv *VersionView
572		for i := range first {
573			switch first[i].VersionID {
574			case "old":
575				old = &first[i]
576			case "new":
577				nv = &first[i]
578			}
579		}
580		if old.End == nil || !old.End.Equal(at(100)) || old.EffectiveEnd == nil || !old.EffectiveEnd.Equal(at(40)) {
581			t.Fatalf("unexpected old view: %+v", old)
582		}
583		if nv.End != nil || nv.EffectiveEnd != nil {
584			t.Fatalf("new should be open-ended: %+v", nv)
585		}
586	
587		// 调用方为展示目的改写这份查询结果
588		*old.End = at(99)
589		*old.EffectiveEnd = at(98)
590		twelve := at(12)
591		nv.End = &twelve
592		nv.EffectiveEnd = &twelve
593	
594		// 再次查询仍是账本中的真实边界
595		second, err := b.ItemVersions("seat")
596		if err != nil {
597			t.Fatal(err)
598		}
599		var old2, nv2 *VersionView
600		for i := range second {
601			switch second[i].VersionID {
602			case "old":
603				old2 = &second[i]
604			case "new":
605				nv2 = &second[i]
606			}
607		}
608		if old2.End == nil || !old2.End.Equal(at(100)) {
609			t.Fatalf("registered end changed through query mutation: %v", old2.End)
610		}
611		if old2.EffectiveEnd == nil || !old2.EffectiveEnd.Equal(at(40)) {
612			t.Fatalf("effective end changed through query mutation: %v", old2.EffectiveEnd)
613		}
614		if nv2.End != nil || nv2.EffectiveEnd != nil {
615			t.Fatalf("open-ended version got an end through another view: %+v", nv2)
616		}
617	
618		// 第一份结果内部：登记结束与实际结束即使值相同，修改一项也不连带另一项
619		equalEnd := at(100)
620		must(RegisterRequest{ItemID: "hall", VersionID: "v", UnitPrice: 1, Start: at(0), End: &equalEnd})
621		h1, _ := b.ItemVersions("hall")
622		h2, _ := b.ItemVersions("hall")
623		if h1[0].End == h1[0].EffectiveEnd {
624			t.Fatal("registered end and effective end share one pointer")
625		}
626		if h1[0].End == h2[0].End {
627			t.Fatal("separate queries share the registered-end pointer")
628		}
629		if h1[0].EffectiveEnd == h2[0].EffectiveEnd {
630			t.Fatal("separate queries share the effective-end pointer")
631		}
632		*h1[0].End = at(50)
633		if !h1[0].EffectiveEnd.Equal(at(100)) {
634			t.Fatalf("editing registered end leaked to effective end: %v", h1[0].EffectiveEnd)
635		}
636		if !h2[0].End.Equal(at(100)) {
637			t.Fatalf("editing one query result leaked to another: %v", h2[0].End)
638		}
639	
640		// 报价仍按真实区间处理：40 起 old 已失效
641		setNow(at(45))
642		out, _ := b.Quote(QuoteRequest{RequestID: "q-old", ItemID: "seat", VersionID: "old", Quantity: 1})
643		if out.Confirmed || out.Reason != ReasonVersionExpired {
644			t.Fatalf("quote must use ledger boundary: %+v", out)
645		}
646	}
